from construire import Chapter,fig,box,qs,sub
from figures_communes import plot
from nouveaux_communs import diagnostic,exercices,bilan,TP12,TD7
from math import pi,sqrt,atan

def create():
 c=Chapter(6,'Régime sinusoïdal forcé et résonance','1.4 / régime sinusoïdal forcé','les impédances complexes, la réponse forcée des oscillateurs électriques et mécaniques, les résonances et leur caractérisation expérimentale.')
 c.f('rlc-force',r'''\draw(0,0)to[V](0,3)to[R,l=$R$](3,3)to[L,l=$L$](6,3)to[C,l=$C$](6,0)--(0,0);\draw[-{Stealth},otGreenDark,thick](-.8,.2)--(-.8,2.8)node[midway,left]{$e$};\draw[-{Stealth},otNavy,thick](1,3.6)--(2.2,3.6)node[midway,above]{$i$};\draw[-{Stealth},otGreenDark,thick](7,.2)--(7,2.8)node[midway,right]{$u_C$};\node[lab,text width=4cm,align=left]at(10,1.4){$R$ désigne toutes les pertes série.\\$e=u_R+u_L+u_C$.};''')
 c.f('fresnel',r'''\draw[axis](0,0)--(8,0)node[right]{Réel};\draw[axis](0,-2)--(0,4)node[above]{Imaginaire};\draw[-{Stealth},otNavy,very thick](0,0)--(5,0)node[midway,below]{$RI_m$};\draw[-{Stealth},otGreenDark,thick](5,0)--(5,3)node[midway,right]{$L\omega I_m$};\draw[-{Stealth},otOrange,thick](5,3)--(5,1.3)node[midway,left]{$I_m/(C\omega)$};\draw[-{Stealth},otNavy,very thick](0,0)--(5,1.3)node[midway,above]{$\underline E$};\draw[otMuted](1,0)arc(0:14.57:1);\node[lab]at(1.6,.35){$\arg Z$};\node[lab,text width=3cm,align=left]at(10,2){Courant de référence réel.\\Cas inductif : $L\omega>1/(C\omega)$.};''')
 plot(c,'resonance-i',[('1/sqrt(1+4*(x-1/x)^2)','Q = 2','otNavy'),('1/sqrt(1+25*(x-1/x)^2)','Q = 5','otGreenDark')],xmax=2,ymin=0,ymax=1.12,xlabel=r'$\omega/\omega_0$',ylabel=r'$I_m/(E_m/R)$',extra=r'\draw[dashed,otMuted](axis cs:0,.7071)--(axis cs:2,.7071);')
 # Éviter la singularité de la formule en zéro dans pgfplots.
 c.figures['resonance-i']=c.figures['resonance-i'].replace('domain=0:2','domain=0.04:2')
 plot(c,'resonance-c',[('1/sqrt((1-x^2)^2+x^2/4)','Q = 2','otNavy'),('1/sqrt((1-x^2)^2+4*x^2)','Q = 0,5','otGreenDark')],xmax=2.5,ymin=0,ymax=2.3,xlabel=r'$\omega/\omega_0$',ylabel=r'$U_{Cm}/E_m$')
 plot(c,'phase',[('-atan(2*(x-1/x))','Phase du courant, Q = 2','otNavy')],xmax=3,ymin=-95,ymax=95,xlabel=r'$\omega/\omega_0$',ylabel=r'$\varphi_i$ (degrés)')
 c.figures['phase']=c.figures['phase'].replace('domain=0:3','domain=0.03:3')
 c.intro='Un excitateur impose sa fréquence ; le système choisit l’amplitude et le déphasage de sa réponse. La résonance est une amplification sélective : sa position dépend de la grandeur observée. Le courant d’un RLC et la tension de sa capacité n’ont donc pas nécessairement leur maximum à la même fréquence.'
 c.mapping=r'Impédances de R, L et C ; associations série et parallèle ; représentation complexe ; réponse électrique et mécanique à une excitation sinusoïdale ; acuité et facteur de qualité ; identification à partir de courbes d’amplitude et de phase ; mesure d’une résonance.'
 c.prereq=r'Chapitre 5 : équation canonique, $\omega_0$, Q, extinction du transitoire. Nombres complexes : module, argument et quotient. Dérivation d’un sinus ; amplitude et valeur efficace.'
 c.method='Fixer la convention temporelle ; construire les impédances ; calculer une amplitude complexe ; prendre module et argument ; étudier les limites ; identifier la grandeur qui résonne ; confronter à une mesure.'
 c.boundary='La puissance moyenne est établie par moyenne temporelle ; aucune théorie de puissance complexe n’est nécessaire.'
 diagnostic(c,[(r'$s=3\cos(200t+\pi/6)$ V : amplitude, pulsation, fréquence et phase ?',r'$S_m=3$ V ; $\omega=200$ rad/s ; $f=100/\pi=31{,}83$ Hz ; $\varphi=\pi/6$.'),(r'Calculer module et argument de $3+4j$.',r'Module 5 ; argument $\arctan(4/3)=53{,}13^\circ$.'),(r'Que vaut $1/j$ ?',r'$1/j=-j$ car $j^2=-1$.'),(r'Dériver $A\cos\omega t$.',r'$-A\omega\sin\omega t=A\omega\cos(\omega t+\pi/2)$.'),(r'Quelle fréquence subsiste après extinction du transitoire d’un système linéaire forcé ?',r'Celle de la source, si l’entrée ne contient qu’une fréquence et si le régime stable existe.'),(r'Une tension d’amplitude 10 V a quelle valeur efficace ?',r'$10/\sqrt2=7{,}071$ V pour une sinusoïde sans composante continue.'),(r'Rappeler $\omega_0$ et Q du RLC série.',r'$\omega_0=1/\sqrt{LC}$ et $Q=L\omega_0/R=\sqrt{L/C}/R$.'),(r'Une phase de sortie négative signifie quoi ?',r'La sortie retarde sur l’entrée, avec la convention $\cos(\omega t+\varphi)$ et une comparaison à fréquence commune.')])
 c.c('Du transitoire au régime établi',sub('Deux contributions',r'Pour un oscillateur stable, la solution complète est la somme d’une solution libre et d’une solution particulière forcée. La première dépend des conditions initiales et s’éteint ; la seconde est à la fréquence de la source. Les calculs de ce chapitre portent sur cette seconde contribution. Ils ne permettent pas de décrire l’allumage à eux seuls.')+box('loi','Équation canonique',r'\[\ddot s+\frac{\omega_0}{Q}\dot s+\omega_0^2s=\omega_0^2 S_e\cos\omega t.\]Les paramètres $\omega_0$ et Q caractérisent le système ; $\omega$ est choisi par l’excitateur. Le régime établi est $s=S_m\cos(\omega t+\varphi)$.')+sub('Attendre avant de mesurer',r'En régime sous-amorti, l’enveloppe libre varie comme $e^{-\omega_0t/(2Q)}$. Attendre plusieurs durées $2Q/\omega_0$ après chaque changement de fréquence. Un Q élevé donne un pic étroit mais un établissement lent. Cette observation relie les chapitres 5 et 6.')+box('piege','Trois pulsations à distinguer',r'La pulsation propre $\omega_0$, la pulsation libre amortie $\omega_d$ et la pulsation du maximum de réponse ne sont pas interchangeables. Nommer systématiquement la grandeur observée.'))
 c.c('La représentation complexe',box('loi','Convention unique dans tout le chapitre',r'\[s(t)=\Re\{\underline S e^{j\omega t}\},\qquad \underline S=S_m e^{j\varphi}.\]$\underline S$ est une amplitude complexe constante. Dans cette convention, dériver revient à multiplier par $j\omega$ ; intégrer une composante non continue revient à diviser par $j\omega$.')+sub('Pourquoi le calcul fonctionne',r'Les équations différentielles sont linéaires à coefficients réels. Leur partie réelle est donc une solution réelle. Par exemple $\ddot s$ est représenté par $-\omega^2\underline S$, ce qui transforme une équation différentielle en relation algébrique. Prendre la partie réelle à la fin, après avoir calculé module et phase.')+sub('Exemple',r'Pour $\dot s+s/\tau=e/\tau$, on obtient $(1+j\omega\tau)\underline S=\underline E$. Donc $S_m=E_m/\sqrt{1+(\omega\tau)^2}$ et $\varphi=-\arctan(\omega\tau)$. À $\omega\tau=1$, l’amplitude est divisée par $\sqrt2$ et le retard vaut $45^\circ$.')+box('methode','Reconstruire le signal',r'Si $\underline S=2-2j$ V, alors $S_m=2\sqrt2$ V et $\varphi=-\pi/4$. Écrire $s(t)=2\sqrt2\cos(\omega t-\pi/4)$ V. Le coefficient réel 2 n’est pas l’amplitude.'))
 c.c('Les impédances élémentaires',box('loi','Convention récepteur',r'\[\underline U=Z\underline I,\qquad Z_R=R,\quad Z_L=jL\omega,\quad Z_C=\frac1{jC\omega}.\]R, L et C sont idéaux dans ces expressions ; une bobine réelle peut être modélisée par $r+jL\omega$. Chaque Z s’exprime en ohms.')+sub('Établissement',r'La résistance vérifie $u=Ri$. Pour la bobine $u=L\dot i$, d’où $\underline U=jL\omega\underline I$. Pour la capacité $i=C\dot u$, d’où $\underline I=jC\omega\underline U$. Le courant est en retard de $\pi/2$ sur la tension d’une bobine, et en avance de $\pi/2$ pour un condensateur.')+sub('Limites physiques',r'Quand $\omega$ tend vers zéro, la bobine idéale tend vers un fil et la capacité vers un circuit ouvert. À haute fréquence, les rôles s’inversent dans ce modèle. Ces limites permettent de repérer une erreur de quotient. Elles ne décrivent pas les défauts réels des composants à fréquence arbitrairement élevée.')+box('docu','Application',r'À $\omega=1000$ rad/s, L = 100 mH donne $Z_L=j100\ \Omega$. C = 10 $\mu\mathrm F$ donne $Z_C=-j100\ \Omega$. En série, ces deux tensions peuvent se compenser malgré des amplitudes non nulles.'))
 c.c('Associer et orienter les dipôles',fig('rlc-force','Montage de référence. Le courant traverse tous les dipôles en série ; les tensions de dipôle suivent la convention récepteur.')+box('loi','Série et parallèle',r'\[Z_s=Z_1+Z_2,\qquad Z_p=\frac{Z_1Z_2}{Z_1+Z_2}.\]Ces formules découlent respectivement de la loi des mailles et de la loi des nœuds. Le diviseur de tension donne $\underline U_2=\underline E Z_2/(Z_1+Z_2)$ uniquement pour les deux impédances réellement en série.')+sub('Une charge modifie le circuit',r'Un voltmètre ou un étage suivant possède une impédance d’entrée. S’il est en parallèle avec C, remplacer $Z_C$ par $Z_C\parallel Z_e$ avant d’utiliser le diviseur. La résistance interne du GBF appartient aux pertes si $\underline E$ désigne sa f.é.m. à vide ; elle n’est pas à ajouter une seconde fois si l’on utilise la tension mesurée aux bornes du RLC.'))
 c.c('Le courant du RLC série',box('loi','Réponse en courant',r'\[Z=R+j\left(L\omega-\frac1{C\omega}\right),\quad \underline I=\frac{\underline E}{Z}.\]\[I_m=\frac{E_m/R}{\sqrt{1+Q^2(x-1/x)^2}},\quad x=\omega/\omega_0.\]\[\varphi_i=-\arctan[Q(x-1/x)].\]L’argument du dénominateur est dans $]-\pi/2,\pi/2[$ puisque R est positif.')+fig('resonance-i','Maximum du courant à x = 1 pour tout Q positif. La droite pointillée indique le niveau de demi-puissance.')+sub('Lecture des limites',r'À basse fréquence, le condensateur bloque et le courant est en avance ; à haute fréquence, la bobine limite le courant et celui-ci retarde. À $\omega_0$, Z = R, $I_m=E_m/R$ et le courant est en phase avec la source.'))
 c.c('La construction de Fresnel',fig('fresnel','Addition des tensions complexes dans le cas inductif. Les vecteurs de L et C ont des directions opposées.')+sub('Une addition vectorielle',r'Choisir le courant comme référence de phase ne change aucune tension physique. $\underline U_R$ est réel, $\underline U_L$ vertical vers le haut et $\underline U_C$ vertical vers le bas. Leur somme est la tension source. Le théorème de Pythagore donne directement le module de Z ; l’angle de la somme donne l’avance de la tension sur le courant.')+box('piege','Les amplitudes ne s’additionnent pas',r'En général $E_m\neq U_{Rm}+U_{Lm}+U_{Cm}$. À la résonance, $U_{Lm}=U_{Cm}=QE_m$ et leurs amplitudes peuvent dépasser $E_m$. Ce sont les amplitudes complexes qui satisfont la loi des mailles.')+box('methode','Contrôle numérique',r'R = 20 $\Omega$, L = 0,10 H et C = 10 $\mu\mathrm F$ donnent $\omega_0=1000$ rad/s, Q = 5. Sous $E_m=2$ V, $I_m=0{,}10$ A à la résonance, et les amplitudes sur L et C valent chacune 10 V.'))
 c.c('La résonance en tension',box('loi','Tension aux bornes du condensateur',r'\[\frac{\underline U_C}{\underline E}=\frac1{1-x^2+jx/Q},\qquad \frac{U_{Cm}}{E_m}=\frac1{\sqrt{(1-x^2)^2+x^2/Q^2}}.\]Le minimum du dénominateur au carré est obtenu pour $x_r^2=1-1/(2Q^2)$. Un maximum à fréquence non nulle existe donc seulement si $Q>1/\sqrt2$.')+fig('resonance-c','Résonance en tension pour Q = 2 ; aucune bosse à fréquence non nulle pour Q = 0,5.')+sub('Valeur du maximum',r'\[\omega_r=\omega_0\sqrt{1-\frac1{2Q^2}},\qquad \frac{U_{Cm,\max}}{E_m}=\frac Q{\sqrt{1-1/(4Q^2)}}.\]À $\omega_0$, le gain vaut exactement Q, sans que ce soit exactement le maximum. Pour Q grand seulement, $\omega_r\simeq\omega_0$ et le gain maximal est proche de Q.'))
 c.c('Phase et identification',fig('phase','Phase du courant : passage par zéro à la résonance, avance à basse fréquence et retard à haute fréquence.')+sub('Choisir le bon quadrant',r'Pour la capacité, $\varphi_C=-\operatorname{atan2}(x/Q,1-x^2)$ : la phase passe de 0 à $-\pi$, et vaut $-\pi/2$ à $\omega_0$. Employer seulement $-\arctan[(x/Q)/(1-x^2)]$ sans corriger le quadrant donne une erreur de $\pi$ au-dessus de la résonance.')+box('methode','Identifier les paramètres',r'Le zéro de la phase du courant ou la phase $-\pi/2$ de $u_C$ donnent $\omega_0$. Le gain $U_{Cm}/E_m$ à cette pulsation donne Q. Une bosse en tension donne $\omega_r$, que l’on convertit avec la relation précédente. Vérifier l’accord des deux méthodes.')+sub('De la date à la phase',r'Si la sortie est retardée d’une durée positive $\Delta t<T/2$, $\varphi_s-\varphi_e=-2\pi\Delta t/T$. La lecture se fait entre deux événements homologues, par exemple deux passages croissants par zéro. La mesure est définie modulo $2\pi$ ; suivre la courbe en fréquence pour dérouler la phase.'))
 c.c('Largeur de bande et facteur de qualité',box('loi','Bande à demi-puissance du courant',r'Les coupures satisfont $I_m=I_{m,\max}/\sqrt2$, donc $|Q(x-1/x)|=1$.\[x_\pm=\sqrt{1+\frac1{4Q^2}}\pm\frac1{2Q},\quad x_-x_+=1.\]\[\Delta\omega=\omega_+-\omega_-=\frac{\omega_0}{Q},\quad Q=\frac{f_0}{f_+-f_-}.\]Ces résultats sont exacts pour le courant du RLC série, avec R constante.')+sub('Exemple résolu',r'Pour $f_0=1000$ Hz et Q = 5 : $f_-=904{,}99$ Hz, $f_+=1104{,}99$ Hz et $\Delta f=200$ Hz. La moyenne arithmétique des coupures vaut 1004,99 Hz, tandis que leur moyenne géométrique vaut exactement 1000 Hz. Il faut donc éviter de remplacer systématiquement $f_0$ par leur milieu.')+box('piege','Le niveau de référence',r'Le facteur $1/\sqrt2$ s’applique à une amplitude ; le facteur 1/2 s’applique à sa puissance. Pour la tension sur C, utiliser sans justification la même largeur $\omega_0/Q$ n’est pas exact. À grand Q, les courbes près du pic deviennent voisines.'))
 c.c('L’analogie mécanique',box('loi','Masse, ressort et frottement fluide',r'\[m\ddot x+b\dot x+kx=F_m\cos\omega t,\quad \omega_0=\sqrt{k/m},\quad Q=\frac{m\omega_0}{b}.\]\[\underline X=\frac{F_m/k}{1-x_r^2+jx_r/Q},\qquad x_r=\omega/\omega_0.\]Le symbole $x_r$ désigne ici une fréquence réduite, pas la position.')+sub('Position et vitesse ne résonnent pas pareil',r'L’amplitude de position a la même réponse que la tension de C. Elle possède un maximum non nul si $Q>1/\sqrt2$. Comme $\underline V=j\omega\underline X$, la vitesse résonne à $\omega_0$ pour tout Q positif. Son maximum vaut $F_m/b$. La vitesse est alors en phase avec la force tandis que la position retarde de $\pi/2$.')+sub('Sens physique',r'À très basse fréquence, le ressort s’adapte presque statiquement : $X_m\simeq F_m/k$. À très haute fréquence, l’inertie domine : $X_m\simeq F_m/(m\omega^2)$. Le frottement dissipe et limite les amplitudes. Si b = 0 à la résonance exacte, le régime permanent sinusoïdal borné supposé n’existe plus.')+box('docu','Correspondances',r'$u_C\leftrightarrow x$, $i\leftrightarrow\dot x$, L $\leftrightarrow$ m, R $\leftrightarrow$ b et $1/C\leftrightarrow$ k, à des facteurs d’échelle de source près.'))
 c.c('Énergie reçue et dissipation',sub('Calcul de la puissance moyenne',r'Pour $u=U_m\cos\omega t$ et $i=I_m\cos(\omega t-\theta)$, le produit des cosinus donne\[\langle ui\rangle=\frac{U_m I_m}2\cos\theta.\]Dans le RLC série, cette puissance vaut $RI_m^2/2=RI_{\rm eff}^2$. Les moyennes des puissances reçues par L et C sont nulles en régime établi : leur énergie stockée retrouve sa valeur après une période.')+box('loi','Bilan sur une période',r'\[\frac{\dd}{\dd t}\left(\frac12Li^2+\frac12Cu_C^2\right)=ei-Ri^2.\]La moyenne du membre de gauche est nulle. À la résonance en courant, $\langle P\rangle=E_m^2/(2R)$, maximum pour une amplitude source fixée.')+sub('Interpréter la sélectivité',r'À la résonance, les échanges réversibles entre L et C sont importants ; la source compense les pertes. Un Q élevé correspond à de faibles pertes relativement à l’énergie échangée. Dans un montage réel, mesurer R totale et surveiller la surtension : la résistance de la bobine ou du générateur peut limiter Q avant la résistance choisie.')+box('methode','Dernier contrôle',r'Une puissance moyenne négative reçue par une résistance positive signale une incohérence d’orientation ou de phase. Une puissance moyenne nulle de L n’implique pas que sa puissance instantanée soit toujours nulle.'))
 c.tp_title='Mesurer une courbe de résonance'
 c.tp=fig('rlc-force','Placer la résistance de mesure au potentiel de masse pour mesurer $u_R$ sans relier deux points distincts par les masses de l’oscilloscope.')+sub('Protocole',r'Utiliser L = 100 mH, C = 10 $\mu\mathrm F$ et une résistance totale voisine de 20 $\Omega$. Mesurer R totale. Observer simultanément la tension e aux bornes du circuit et $u_R$ sur une résistance accessible de valeur connue $R_m$. Garder $E_m$ constant ; déduire $I_m=U_{Rm}/R_m$. Après stabilisation, relever amplitude et phase pour une quinzaine de fréquences, plus serrées près du pic.')+sub('Données simulées pour s’entraîner',r'Un jeu idéal donne $f_0=159{,}15$ Hz, $f_-=144{,}03$ Hz et $f_+=175{,}86$ Hz. Estimer Q et R totale. Avec des incertitudes-types indépendantes $u(f_0)=0{,}20$ Hz et $u(f_\pm)=0{,}30$ Hz, propager l’incertitude sur Q.')+box('methode','Exploitation attendue',r'$\Delta f=31{,}83$ Hz, Q = 5,00 et $R=L(2\pi f_0)/Q=20{,}0\ \Omega$. $u(\Delta f)=0{,}424$ Hz et $u(Q)/Q=\sqrt{[u(f_0)/f_0]^2+[u(\Delta f)/\Delta f]^2}$ donnent $u(Q)=0{,}067$. Comparer au Q calculé avec les composants, sans confondre désaccord et erreur certaine.')
 c.f('rlc-mesure',r'''\draw(0,0)to[V](0,3)to[R,l=$r$](2,3)to[L,l=$L$](4.5,3)to[C,l=$C$](7,3)to[R,l=$R_m$](7,0)--(0,0);\node[ground]at(0,0){};\draw[-{Stealth},otGreenDark,thick](-.8,.2)--(-.8,2.8)node[midway,left]{$e$};\draw[-{Stealth},otNavy,thick](.4,3.8)--(1.6,3.8)node[midway,above]{$i$};\draw[-{Stealth},otGreenDark,thick](8,.2)--(8,2.8)node[midway,right]{$u_{R_m}$};\node[lab,text width=3.5cm,align=left]at(11,1.4){Voie 1 : $e$.\\Voie 2 : $u_{R_m}$.\\Masses au nœud du bas.\\$R_{\rm totale}=r+R_m$.};''')
 c.tp=c.tp.replace(r'\fig{rlc-force}',r'\fig{rlc-mesure}')
 c.num_title='Comparer trois résonances'
 c.num=r'''Le code trace les réponses réduites du courant et de la tension de C pour Q = 0,5 ; 2 ; 5. Les graphes sont calculés sur la même grille ; le tableau donne la position numérique des maxima.
\begin{verbatim}
import numpy as np
import matplotlib.pyplot as plt
x = np.linspace(0.001, 3, 30000)
peaks = []
fig, axes = plt.subplots(2, 1)
for Q in (0.5, 2., 5.):
    gi = 1 / np.sqrt(1 + Q**2*(x-1/x)**2)
    gc = 1 / np.sqrt((1-x*x)**2 + (x/Q)**2)
    peaks.append((Q, x[gi.argmax()], x[gc.argmax()]))
    axes[0].plot(x, gi, label=f"Q={Q}")
    axes[1].plot(x, gc, label=f"Q={Q}")
for ax in axes:
    ax.legend(); ax.grid()
    ax.set_xlabel("omega / omega0")
axes[0].set_ylabel("I / (E/R)")
axes[1].set_ylabel("Uc / E")
plt.tight_layout()
\end{verbatim}
\Sub{Travail et interprétation}
Retrouver $x_i=1$ pour tous les Q. Pour Q = 2 et 5, comparer les maxima en tension à $\sqrt{1-1/(2Q^2)}$, soit 0,9354 et 0,98995. Pour Q = 0,5, le maximum sur la grille est au bord bas : la courbe n’a pas de résonance à fréquence non nulle. Réduire le pas de grille pour distinguer erreur de discrétisation et écart physique.
'''
 bilan(c,r'$Z_R=R$, $Z_L=jL\omega$, $Z_C=1/(jC\omega)$. Pour le RLC série : $\omega_0=1/\sqrt{LC}$, $Q=\sqrt{L/C}/R$. Courant : maximum à $\omega_0$, largeur $\omega_0/Q$. Tension de C : maximum à $\omega_0\sqrt{1-1/(2Q^2)}$ si $Q>1/\sqrt2$.',r'Nommer l’entrée et la sortie ; fixer les orientations ; écrire Z ; contrôler les unités ; calculer module et phase ; vérifier basses et hautes fréquences ; relier le calcul aux courbes. Une identification utilise au moins deux lectures indépendantes.',r'Employer une pulsation à la place d’une fréquence ; additionner des modules ; oublier une résistance interne ; imposer une condition initiale à la seule réponse permanente ; confondre résonance de position et de vitesse.')
 c.td_titles=['Lire un sinus','Calculer une impédance','Déterminer le courant','Résonance en tension','Lire amplitude et phase','Énergie et largeur','Passer à la mécanique','Discuter un modèle']
 exercices(c,[
 ('Une phase temporelle',r'$e=4\cos(500t+\pi/3)$ V. Donner $\underline E$, f et la valeur efficace. Écrire l’amplitude complexe de $\dot e$.',r'$\underline E=4e^{j\pi/3}=2+2\sqrt3j$ V ; $f=500/(2\pi)=79{,}58$ Hz ; $E_{\rm eff}=2\sqrt2$ V. La dérivée a pour amplitude $j500\underline E$, de module 2000 V/s et de phase $5\pi/6$.'),
 ('Revenir au réel',r'$\underline S=-3+3j$ V. Écrire $s(t)$ à $\omega=100$ rad/s.',r'Module $3\sqrt2$ V, argument $3\pi/4$ dans le deuxième quadrant. Donc $s=3\sqrt2\cos(100t+3\pi/4)$ V. La tangente seule ne distingue pas les quadrants.'),
 ('Mesurer un retard',r'À f = 200 Hz, une sortie présente un retard de 0,625 ms sur l’entrée. Calculer sa phase relative.',r'T = 5 ms ; $\varphi=-2\pi(0{,}625/5)=-\pi/4$. Le signe négatif traduit le retard dans la convention du cours.'),
 ('Bobine et condensateur',r'À f = 50 Hz, calculer Z pour L = 200 mH et pour C = 100 $\mu\mathrm F$.',r'$Z_L=j20\pi=j62{,}83\ \Omega$ ; $Z_C=-j100/\pi=-j31{,}83\ \Omega$. Les deux modules ne sont pas égaux.'),
 ('Une série RL',r'R = 30 $\Omega$, $L\omega=40\ \Omega$ et $E_m=10$ V. Déterminer le courant et sa phase.',r'$Z=30+40j\ \Omega$, $|Z|=50\ \Omega$. $I_m=0{,}20$ A, $\varphi_i=-\arctan(4/3)=-53{,}13^\circ$. La valeur efficace est 0,1414 A.'),
 ('Un parallèle RC',r'R = 100 $\Omega$ et $1/(C\omega)=100\ \Omega$. Calculer $Z_R\parallel Z_C$.',r'$Y=1/R+jC\omega=0{,}01(1+j)$ S, donc $Z=50-50j\ \Omega$, de module $50\sqrt2\ \Omega$. Une association parallèle se traite commodément avec les admittances.'),
 ('La résonance du courant',r'R = 20 $\Omega$, L = 100 mH, C = 10 $\mu\mathrm F$, $E_m=2$ V. Donner $\omega_0$, f0, Q et le courant maximal.',r'$\omega_0=1000$ rad/s, $f_0=159{,}15$ Hz, Q = 5 et $I_{m,\max}=0{,}10$ A. Le maximum est obtenu lorsque la partie imaginaire de Z s’annule.'),
 ('De part et d’autre',r'Pour les données de E07, calculer $I_m$ et $\varphi_i$ à $\omega=500$ puis 2000 rad/s.',r'Les fréquences réduites sont 0,5 et 2, avec $Q(x-1/x)=\mp7{,}5$. Dans les deux cas $I_m=0{,}1/\sqrt{57{,}25}=13{,}22$ mA. Les phases valent respectivement $+82{,}41^\circ$ et $-82{,}41^\circ$.'),
 ('Des tensions supérieures à la source',r'À la résonance de E07, donner les amplitudes des trois tensions. Vérifier la maille complexe.',r'$U_{Rm}=2$ V ; $U_{Lm}=U_{Cm}=10$ V. Avec le courant réel : $\underline U_R=2$, $\underline U_L=10j$, $\underline U_C=-10j$ V ; leur somme est bien 2 V.'),
 ('Un pic déplacé',r'Un oscillateur a Q = 2 et $\omega_0=100$ rad/s. Donner la pulsation du maximum en position et le gain maximal réduit.',r'$\omega_r=100\sqrt{7/8}=93{,}54$ rad/s. Le gain maximal est $2/\sqrt{15/16}=8/\sqrt{15}=2{,}066$. À $\omega_0$, le gain n’est que 2.'),
 ('Existe-t-il une résonance ?',r'Comparer le gain en tension de C pour Q = 0,60 et Q = 0,80. Lequel présente une bosse ?',r'Le seuil est $1/\sqrt2\simeq0{,}7071$. Q = 0,60 : décroissance depuis la valeur statique. Q = 0,80 : maximum non nul à $x_r=\sqrt{7/32}=0{,}4677$. Un régime libre oscillant, possible dès Q > 0,5, ne garantit donc pas cette bosse.'),
 ('Une tension et sa phase',r'Pour $x=1$ et Q = 3, écrire $\underline U_C/\underline E$ et interpréter.',r'$H=1/(j/3)=-3j$. Gain 3 et phase $-\pi/2$. La tension de C retarde d’un quart de période ; le courant est en phase avec la source.'),
 ('Identifier avec la phase',r'La phase de $u_C/e$ vaut $-90^\circ$ à 120 Hz, où le gain vaut 4. Déterminer f0, Q et fr.',r'$f_0=120$ Hz, Q = 4. $f_r=120\sqrt{1-1/32}=118{,}11$ Hz. Ces conclusions supposent la forme canonique du RLC et l’absence de charge parasite importante.'),
 ('Deux coupures',r'Le courant atteint son maximum à 1,00 kHz ; ses coupures à demi-puissance sont séparées de 100 Hz. Déterminer Q et leurs valeurs exactes.',r'Q = 10. $f_\pm=1000[\sqrt{1+1/400}\pm1/20]$, soit 951,25 et 1051,25 Hz. Leur produit vaut $f_0^2$.'),
 ('Passer d’une date à un graphe',r'À 250 Hz, $u_R$ est en avance de 0,50 ms sur e. Trouver $Q(x-1/x)$.',r'$\varphi_i=+\pi/4$. Puisque $\varphi_i=-\arctan[Q(x-1/x)]$, on a $Q(x-1/x)=-1$. C’est la coupure basse du courant.'),
 ('Puissance moyenne',r'Une source de valeur efficace 5 V alimente une impédance $30+40j\ \Omega$. Calculer la puissance moyenne reçue.',r'$I_{\rm eff}=5/50=0{,}10$ A et $\cos\theta=30/50=0{,}60$. $P=5\times0{,}10\times0{,}60=0{,}30$ W, également $RI_{\rm eff}^2$.'),
 ('La résistance manquante',r'L = 50 mH, C = 2 $\mu\mathrm F$ et Q mesuré = 5. La résistance ajoutée est 20 $\Omega$. Trouver les autres pertes série.',r'$\sqrt{L/C}=158{,}11\ \Omega$ ; R totale = 31,62 $\Omega$. Les pertes non comptées valent donc 11,62 $\Omega$. Si la tension d’entrée est mesurée sur le seul RLC, la résistance interne du GBF est exclue de ce R totale.'),
 ('Quand mesurer ?',r'$\omega_0=1000$ rad/s et Q = 20. Quel temps réduit le transitoire d’un facteur 100 ?',r'La constante d’enveloppe vaut $2Q/\omega_0=0{,}040$ s. Il faut $t=0{,}040\ln100=0{,}1842$ s. La consigne concerne l’enveloppe du mode libre sous-amorti.'),
 ('Une masse forcée',r'm = 0,20 kg, k = 20 N/m, b = 0,40 kg/s, $F_m=0{,}10$ N. Calculer Q, $\omega_0$ et les amplitudes à $\omega_0$.',r'$\omega_0=10$ rad/s et Q = 5. $X_m=F_m/(b\omega_0)=0{,}025$ m ; $V_m=F_m/b=0{,}25$ m/s. La position retarde de $\pi/2$, la vitesse est en phase avec la force.'),
 ('Dissipation mécanique',r'Pour E19 à $\omega_0$, calculer la puissance moyenne et vérifier le bilan.',r'$\langle P_f\rangle=bV_m^2/2=0{,}0125$ W. La force et la vitesse étant en phase, $\langle Fv\rangle=F_mV_m/2=0{,}0125$ W. L’énergie mécanique moyenne ne varie plus.'),
 ('Borne sur Q',r'On impose $\omega_r\geq0{,}99\omega_0$ pour la position. Déterminer la borne minimale de Q.',r'$1-1/(2Q^2)\geq0{,}99^2$ donne $Q\geq[2(1-0{,}9801)]^{-1/2}=5{,}013$. La présence du pic et l’approximation de sa position sont deux exigences distinctes.'),
 ('Une géométrie de coupures',r'Démontrer $\omega_-\omega_+=\omega_0^2$, puis retrouver $\omega_0$ pour des coupures à 900 et 1100 rad/s.',r'Le produit des deux racines réduites $\sqrt{1+1/(4Q^2)}\pm1/(2Q)$ est 1. Donc $\omega_0=\sqrt{900\times1100}=994{,}99$ rad/s et Q = 994,99/200 = 4,975.'),
 ('Un capteur charge la capacité',r'Une résistance d’entrée $R_e$ est placée en parallèle sur C. Écrire l’impédance de sortie, puis le transfert pour un RLC série.',r'$Z_p=[1/R_e+jC\omega]^{-1}$. $H=Z_p/[R+jL\omega+Z_p]$. En développant : $H=1/[1+R/R_e-LC\omega^2+j\omega(RC+L/R_e)]$. L’ancien Q ne s’utilise plus sans recalcul.'),
 ('Une résonance sans pertes ?',r'Pour b = 0 et $\omega=\omega_0$, pourquoi le transfert forcé diverge-t-il ? Quelle conclusion physique faut-il tirer ?',r'L’équation $\ddot x+\omega_0^2x=(F_m/m)\cos\omega_0t$ possède le terme particulier $x_p=F_mt\sin(\omega_0t)/(2m\omega_0)$. Son amplitude croît avec t. Il n’existe pas de régime permanent borné à cette fréquence dans ce modèle idéal ; la divergence n’est pas une amplitude réelle infinie établie instantanément.')])
 c.d('Concevoir une résonance sélective',r'Un RLC série doit résonner en courant à 1,00 kHz avec une largeur de bande de 100 Hz. L = 50,0 mH ; la bobine possède une résistance de 8,0 $\Omega$. La source appliquée au RLC a une amplitude de 1,00 V.'+qs(r'Déterminer C, Q et R totale. En déduire la résistance externe.',r'Calculer les deux fréquences de coupure et la phase du courant en chacune.',r'Calculer le courant maximal, la surtension sur C à f0 et la puissance moyenne.',r'Un capteur ne supporte que 8 V d’amplitude sur C. Peut-on conserver simultanément les caractéristiques imposées ? Proposer une modification de la source.',r'Estimer le délai d’attente pour réduire le transitoire à 1 %.'),'1. La largeur fixe Q. 2. R totale = Lω0/Q. 3. La tension sur C à f0 vaut QE. 4. Modifier l’amplitude ne change pas les paramètres d’un modèle linéaire.',r'C = $1/[L(2\pi f_0)^2]=0{,}5066\ \mu\mathrm F$, Q = 10 et R totale = 31,416 $\Omega$. Ajouter 23,416 $\Omega$. Les coupures sont 951,25 et 1051,25 Hz ; les phases du courant sont $+45^\circ$ et $-45^\circ$. Le courant maximal vaut 31,83 mA et $U_{Cm}(f_0)=10$ V. La puissance moyenne est $1/(2R)=15{,}92$ mW. Le maximum en tension est même légèrement supérieur à 10 V : gain $10/\sqrt{1-1/400}=10{,}0125$. Une limitation à 8 V sur toute la courbe impose $E_m\leq0{,}7990$ V. L et C et les résistances peuvent rester inchangés. La durée d’enveloppe vaut $2Q/\omega_0=3{,}183$ ms ; attendre au moins 14,66 ms pour un facteur 100, puis tenir compte des délais instrumentaux. Un cahier des charges doit préciser la grandeur limitée : courant, tension ou puissance.')
 c.d('Identifier sans connaître les composants',r'Un oscillateur mécanique de masse connue m = 0,20 kg reçoit une force sinusoïdale d’amplitude $F_m=0{,}10$ N. La vitesse maximale vaut 0,25 m/s à $\omega=10$ rad/s. Les coupures à demi-puissance sont distantes de 2 rad/s.'+qs(r'Déterminer b, k et Q de deux manières cohérentes.',r'Prédire la position du maximum de déplacement et son amplitude.',r'Calculer la puissance moyenne reçue à la résonance de vitesse.',r'À $\omega_0$, un relevé annonce que la position est en avance de $90^\circ$ sur la force. Le relevé est-il cohérent ? Quels branchements ou définitions contrôler ?'),'1. Vmax = Fm/b. 2. Δω = b/m. 3. Le déplacement suit le transfert passe-bas du second ordre.',r'$b=F_m/V_{\max}=0{,}40$ kg/s. $k=m\omega_0^2=20$ N/m. $Q=m\omega_0/b=5$ ; la largeur donne aussi Q = 10/2 = 5 et b = mΔω = 0,40 kg/s. Le maximum de déplacement est à $\omega_r=10\sqrt{0{,}98}=9{,}8995$ rad/s. Son amplitude vaut $(F_m/k)Q/\sqrt{1-1/(4Q^2)}=25{,}126$ mm. La puissance moyenne vaut $bV_{\max}^2/2=12{,}5$ mW. La position doit retarder de $90^\circ$ sur la force. Un capteur de déplacement inversé ajoute $\pi$ à la phase et ferait apparaître une avance de $90^\circ$. Vérifier aussi la polarité de la mesure de force et l’ordre des voies. L’accord des modules ne suffit pas à valider la phase.')
 c.d('Les pertes du générateur changent la lecture',r'Un générateur de f.é.m. $E_g$ et de résistance r = 50 $\Omega$ alimente R = 20 $\Omega$, L = 100 mH et C = 10 $\mu\mathrm F$ en série. On peut soit rapporter $u_C$ à $E_g$, soit à la tension e réellement appliquée au groupe RLC.'+qs(r'Établir les deux transferts et calculer leur Q respectif.',r'À $\omega_0$, comparer les gains et la tension réellement appliquée au RLC.',r'Pour chaque transfert, existe-t-il une résonance en tension à fréquence non nulle ?',r'Expliquer pourquoi garder la consigne du GBF constante ne suffit pas à garantir e constante pendant le balayage.'),'1. Écrire la maille en incluant r seulement quand l’entrée est Eg. 2. e = ZRLC I. 3. Une tension mesurée permet de normaliser le transfert.',r'Par rapport à $E_g$, $H_g=1/[1-LC\omega^2+j(R+r)C\omega]$ et $Q_g=100/70=1{,}4286$. Par rapport à e, $H_e=1/[1-LC\omega^2+jRC\omega]$ et $Q_e=5$. À $\omega_0=1000$ rad/s, $|u_C/E_g|=1{,}4286$, $|u_C/e|=5$ et $e/E_g=R/(R+r)=2/7$. Les deux Q dépassent $1/\sqrt2$ : les deux transferts ont une bosse, respectivement à $x_r=\sqrt{1-1/(2Q_g^2)}=0{,}8689$ et 0,98995. La charge du générateur dépend de la fréquence, donc sa chute interne varie. Le rapport $u_C/e$ reste celui du RLC même si e varie ; une courbe de $u_C$ seule avec consigne fixe décrit en revanche tout le montage. Il faut annoncer précisément le port d’entrée utilisé.')
 c.dm_title='DM — Un résonateur à calibrer'
 c.dm=r'Un RLC série possède L = 80,0 mH, C inconnue et R totale inconnue. Sous une tension d’amplitude constante 2,00 V, on mesure $f_0=500$ Hz et un courant maximal de 40,0 mA. Les lectures à demi-puissance donnent $\Delta f=99{,}5$ Hz.'+sub('A. Identification — 8 points',qs(r'Établir le transfert en courant et sa phase. (3)',r'Déterminer C, R totale et Q avec les composants. (3)',r'Comparer au Q donné par la largeur. (2)'))+sub('B. Tension et énergie — 8 points',qs(r'Calculer l’amplitude sur C à f0 et celle du maximum véritable. (3)',r'Donner la fréquence de ce maximum. (2)',r'Établir le bilan énergétique moyen et calculer la puissance reçue à f0. (3)'))+sub('C. Mesure — 4 points',qs(r'Préciser les grandeurs à maintenir constantes, les précautions de masse et le temps de stabilisation à 1 %. (4)'))
 c.dm_sol=sub('A — 8 points',r'$\underline I=\underline E/[R+j(L\omega-1/(C\omega))]$, phase opposée à l’argument du dénominateur (3). R = E/Imax = 50,0 $\Omega$, C = $1/[0{,}080(1000\pi)^2]=1{,}2665\ \mu\mathrm F$, Q = Lω0/R = 5,0265 (3). La largeur donne 500/99,5 = 5,0251, accord avec l’arrondi des données (2).')+sub('B — 8 points',r'À f0, $U_{Cm}=QE_m=10{,}053$ V ; maximum $QE_m/\sqrt{1-1/(4Q^2)}=10{,}103$ V (3). $f_r=f_0\sqrt{1-1/(2Q^2)}=495{,}03$ Hz (2). La variation moyenne des énergies stockées est nulle ; $\langle ei\rangle=RI_m^2/2=0{,}0400$ W (3).')+sub('C — 4 points',r'Mesurer e aux bornes du RLC et maintenir son amplitude, ou normaliser chaque point (1). Placer les masses au même nœud et mesurer le courant par une résistance accessible (1). La constante d’enveloppe vaut $2L/R=3{,}20$ ms ; un facteur 100 demande $3{,}20\ln100=14{,}74$ ms (2). Le barème total est 20.')
 c.ds_title='DS — Deux oscillateurs, une méthode'
 c.ds=[sub('A. Représentation complexe — 6 points',r'On impose $e=3\cos\omega t$ V à un RLC série : R = 30 $\Omega$, L = 60 mH, C = 6,0 $\mu\mathrm F$.'+qs(r'Établir les trois impédances et le courant complexe. (3)',r'Donner $\omega_0$, Q, f0 et le courant maximal. (3)'))+sub('B. Résonance et phase — 8 points',qs(r'Calculer les coupures exactes du courant et leur phase. (3)',r'Calculer la tension de C et sa phase à f0. (2)',r'Le maximum de cette tension se produit-il à f0 ? Calculer sa fréquence et son amplitude. (3)')),
 sub('C. Une expérience mécanique — 6 points',r'Un système masse-ressort présente m = 0,30 kg, k = 30 N/m et b = 0,60 kg/s. On applique $F=0{,}12\cos\omega t$ N.'+qs(r'Déterminer $\omega_0$, Q et le transfert en déplacement. (2)',r'À $\omega_0$, déterminer les amplitudes de position et vitesse et leurs phases relatives à F. (2)',r'Calculer la puissance moyenne et expliquer le rôle du frottement dans le régime établi. (2)'))]
 c.ds_sol=[sub('A — 6 points',r'$Z_R=R$, $Z_L=jL\omega$, $Z_C=1/(jC\omega)$ ; $\underline I=3/[30+j(0{,}060\omega-1/(6\times10^{-6}\omega))]$ (3). $\omega_0=1666{,}67$ rad/s, Q = 10/3, $f_0=265{,}26$ Hz et $I_{m,\max}=0{,}100$ A (3).')+sub('B — 8 points',r'$x_\pm=\sqrt{1+0{,}15^2}\pm0{,}15$, donc $\omega_-=1435{,}31$ et $\omega_+=1935{,}31$ rad/s ; phases $+\pi/4$ et $-\pi/4$ ; largeur 500 rad/s (3). À f0, $U_{Cm}=10{,}0$ V et phase $-\pi/2$ (2). Q dépasse $1/\sqrt2$ ; $\omega_r=1666{,}67\sqrt{0{,}955}=1628{,}73$ rad/s, $f_r=259{,}22$ Hz. Le gain maximal vaut 3,3715, donc $U_{Cm,\max}=10{,}114$ V (3).'),sub('C — 6 points',r'$\omega_0=10$ rad/s ; Q = 5 ; $\underline X=(0{,}12/30)/[1-(\omega/10)^2+j\omega/50]$ m (2). À $\omega_0$, $X_m=0{,}020$ m avec retard $\pi/2$, $V_m=0{,}20$ m/s en phase avec F (2). $P=bV_m^2/2=0{,}012$ W. La source compense exactement la dissipation moyenne, sans augmentation moyenne d’énergie stockée (2).')+box('methode','Lire sa copie',r'Une erreur sur Q se répercute sur la largeur, la surtension et l’établissement. Refaire d’abord l’identification des coefficients de l’équation. Ne pas retirer deux fois les points d’une même erreur de calcul dans les questions dépendantes.')]
 c.hints=r'E06 : utiliser l’admittance. E10 : minimiser le dénominateur au carré. E14 : utiliser les coupures exactes, pas une symétrie arithmétique. E23 : remplacer d’abord la branche C par son parallèle.'
 c.eval_hints=r'DM : la résistance vient directement de la résonance en courant. DS : conserver $\omega_0$ en rad/s jusqu’à la conversion finale ; une dérivation multiplie l’amplitude par $\omega$ et ajoute $\pi/2$ à la phase.'
 c.source('TP publié — Résonance du RLC',TP12,'MPSI, TP12, année 2025–2026, p. 1–2. Sélection : modèle et étude rapide.',r'Refaire la préparation ; mesurer le courant à partir de la résistance. Examiner le rôle du suiveur et de la résistance de bobine. Comparer deux résistances.',r'Le gain maximal de la tension résistive est $R/(R+r)$, tandis que Q dépend de R + r. À résonance, la phase résistive est nulle. La largeur du courant vérifie $\Delta\omega=(R+r)/L$ lorsque l’entrée est mesurée sur le groupe série considéré.')
 c.source('TD publié — Une résonance sélective',TD7,'MPSI, TD7, 2025–2026, exercice 3, p. 1.',r'Traiter les questions 1 à 6 à partir de la fonction fournie ; distinguer gain, gain en décibels et puissance.',r'Le gain est $[1+Q^2(x-1/x)^2]^{-1/2}$. Le maximum vaut 1 à x = 1. Les coupures satisfont $Q|x-1/x|=1$ ; leur différence est $1/Q$ en fréquence réduite. Les pentes asymptotiques sont +20 puis -20 dB par décade.')
 c.next='Le chapitre 7 applique ces réponses fréquentielles au traitement de signaux contenant plusieurs harmoniques.'
