 c.check('Q-DM',.08*1000*pi/50,5.026548245743669)
 c.check('surtension-DS',10/sqrt(1-1/(4*(10/3)**2)),10.114,0.001)
 c.check('pic-D3',sqrt(1-1/(2*(100/70)**2)),.8689073598491384)
 return c
